function question(prompt: string, correct: string, wrong: string[], answer: number, explanation: string): Question {
  if (wrong.length !== 3 || new Set([correct, ...wrong]).size !== 4) throw new Error(`Invalid listening choices: ${prompt}`)
  const options = [...wrong]
  options.splice(answer, 0, correct)
  return [prompt, options, answer, explanation]
}


