const announcementEndings = [
  { text: (l: string) => `If a different procedure is proposed for ${l}, contact the coordinator before acting. Enter any approved change in the shared log so the next team can check what was done.`, prompt: 'Why must an approved change be logged?', correct: 'So the next team can check how an approved change was handled.', wrong: ['So staff can make changes without consulting the coordinator.', 'So the next team can ignore the original procedure.', 'So proposed changes automatically count as approved.'] },
  { text: (l: string) => `For questions about ${l}, speak to the service desk. If a change is authorized, obtain a written record; a spoken agreement alone is not sufficient.`, prompt: 'What is required if a change is authorized?', correct: 'A written record of the authorization is required.', wrong: ['A spoken agreement replaces the written record.', 'Any visitor may authorize a change without asking.', 'The original instruction stops applying to everyone.'] },
  { text: (l: string) => `Before closing, report any unresolved question about ${l} to the supervisor. Do not assume that an unanswered request has been approved.`, prompt: 'What should staff do with an unresolved request?', correct: 'Report it to the supervisor instead of assuming approval.', wrong: ['Treat the lack of a reply as permission to proceed.', 'Approve it themselves after the supervisor leaves.', 'Discard the request without telling the supervisor.'] },
  { text: (l: string) => `If the announced procedure for ${l} cannot be followed, pause and contact the responsible staff member. Resume only after receiving instructions.`, prompt: 'When should listeners resume a paused procedure?', correct: 'After the responsible staff member gives instructions.', wrong: ['As soon as they think of their own substitute procedure.', 'Before telling staff why the procedure was paused.', 'Whenever another participant says it probably looks safe.'] },
  { text: (l: string) => `A checklist for ${l} is posted at the entrance. Sign the checklist after completing the stated action, not merely after reading the notice.`, prompt: 'When should listeners sign the checklist?', correct: 'After completing the action described in the notice.', wrong: ['Immediately after reading the notice, before taking action.', 'Before checking what the notice requires.', 'Only if they choose not to follow the notice.'] },
  { text: (l: string) => `Facility staff handle questions about ${l}. They will document authorized exceptions so that later staff can distinguish an approved change from an error.`, prompt: 'Why will staff document an authorized exception?', correct: 'To distinguish an approved change from a mistake later.', wrong: ['To allow any unapproved change to pass as authorized.', 'To remove the need to consult facility staff.', 'To prevent later staff from seeing what changed.'] },
  { text: (l: string) => `The revised arrangements for ${l} apply to current bookings as well as new requests. An earlier booking does not exempt its holder from this notice.`, prompt: 'Who must follow the revised arrangements?', correct: 'People with earlier bookings as well as new applicants.', wrong: ['Only people making a request for the first time.', 'Everyone except people who booked before this notice.', 'Only people who have not yet received confirmation.'] },
  { text: (l: string) => `Keep the confirmation for ${l} with the related materials. The next shift will use it to verify that the required action was completed.`, prompt: 'Why should the confirmation be kept?', correct: 'So the next shift can verify completion of the required action.', wrong: ['So the next shift can skip the required action without checking.', 'So confirmation can replace completing the required action.', 'So later staff cannot find out what was completed.'] },
]

export function createAdvancedListening(config: AdvancedFormConfig): BaseItem[] {
  const formIndex = config.form - 23
  if (formIndex < 0 || formIndex >= campusReplies.length) throw new Error('Advanced listening supports forms 23–30.')
  const { response, listeningGroup } = createAuthoredFormHelpers(`f${config.form}`)
  const answerAt = (index: number) => (formIndex + index) % 4
  const responses = campusReplies[formIndex].map(([audio, correct, ...wrong], index) => response(index, audio, [...wrong.slice(0, answerAt(index)), correct, ...wrong.slice(answerAt(index))], answerAt(index), `“${audio}”에 대한 직접적이고 자연스러운 응답은 “${correct}”입니다. 다른 선택지는 장소·시간·이유·요청 등 발화가 묻는 사항에 답하지 않습니다.`))

  const conversations = config.conversations.flatMap((brief, index) => {
    const scenario = conversationCases[formIndex][index]
    const audio = `Student: ${scenario.situation} Instructor: ${scenario.reason} This connects to ${brief.label}. ${brief.principle} Student: What would you recommend for this ${brief.label} activity? Instructor: ${scenario.action}`
    const q = [
      question(`What explains the instructor's advice about ${brief.label}?`, scenario.reason, scenario.wrongReasons, answerAt(index * 2), `학생의 상황: “${scenario.situation}” 설명은 “${scenario.reason}”입니다. 다른 선택지는 해당 개념의 원인·조건을 바꾸거나 대화에서 배제한 결론을 단정합니다.`),
      question(`What should the student do next about ${brief.label}?`, scenario.action, scenario.wrongActions, answerAt(index * 2 + 1), `권장한 행동은 “${scenario.action}”입니다. 이 조언은 “${scenario.reason}”라는 문제를 확인하기 위한 것입니다. 나머지 선택지는 확인 대상이나 순서·조건을 잘못 바꿉니다.`),
    ]
    return listeningGroup(`conversation-${index}`, 'Listen to a Conversation', brief.topic, 'B2', audio, q)
  })

  const announcements = config.announcements.flatMap((brief, index) => {
    const ending = announcementEndings[formIndex]
    const audio = `${brief.notice} ${ending.text(brief.label)}`
    const correctAction = noticeActionOverrides[brief.label] || brief.inference
    const q = [
      question(`What action follows from the ${brief.label} notice?`, correctAction, noticeAlternatives[formIndex][index], answerAt(index * 2), `공지 원문: “${brief.notice}” 따라서 필요한 행동은 “${correctAction}”입니다. 다른 선택지는 그 공지의 시점·예외·처리 순서·접근 조건 중 하나를 잘못 바꿉니다.`),
      question(`${ending.prompt.slice(0, -1)} in the ${brief.label} notice?`, ending.correct, ending.wrong, answerAt(index * 2 + 1), `추가 안내는 “${ending.text(brief.label)}”입니다. 정답은 실제로 말한 행동과 목적을 연결합니다. 지문에 없는 공유 로그를 전제하지 않습니다.`),
    ]
    return listeningGroup(`announcement-${index}`, 'Listen to an Announcement', brief.topic, brief.difficulty || 'B2', audio, q)
  })

  const talks = config.talks.flatMap((brief, index) => {
    const check = talkChecks[brief.label]
    if (!check) throw new Error(`Missing academic listening check: ${brief.label}`)
    const shortcut = check.wrong[0].charAt(0).toLowerCase() + check.wrong[0].slice(1, -1)
    const audio = `${brief.principle} A tempting shortcut in interpreting ${brief.label} would be to ${shortcut}. That approach is insufficient because ${check.caution.charAt(0).toLowerCase()}${check.caution.slice(1)} Instead, the lecturer recommends a more specific check for ${brief.label}: ${check.action}`
    return listeningGroup(`talk-${index}`, 'Listen to an Academic Talk', brief.topic, brief.difficulty || 'C1', audio, [
      question(`Which statement expresses the central idea of ${brief.label}?`, brief.principle, competingIdeas[brief.label] || (() => { throw new Error(`Missing topic-specific alternatives: ${brief.label}`) })(), answerAt(index * 2), `핵심 개념은 “${brief.principle}”입니다. 나머지 세 선택지는 개념의 조건·원인·결과를 바꾸거나, 가능성을 항상 성립하는 결과로 과장합니다.`),
      question(`Which follow-up does the lecturer propose for ${brief.label}?`, check.action, check.wrong, answerAt(index * 2 + 1), `주의사항: “${check.caution}” 권장한 확인: “${check.action}” 오답은 강의가 경계한 구체적인 추론 오류(비교 대상·시간·조건·자료 누락)를 반복하거나 다른 확인 대상으로 바꿉니다.`),
    ])
  })
  // Match the original helper's two-module arrangement and preserve every ID.
  return [
    ...responses.slice(0, 9), ...conversations.slice(0, 5), ...announcements.slice(0, 4), ...talks.slice(0, 6),
    ...responses.slice(9), ...conversations.slice(5), ...announcements.slice(4), ...talks.slice(6),
  ].map((item, index) => ({ ...item, module: index < 24 ? 1 : 2 }))
}
